def render_entry(n, title, severity, status, desc, impact, root_cause, files, fix, category):
    sev_icon = {"Critical": "🔴 Critical", "High": "🔴 High", "Medium": "🟡 Medium", "Low": "🟢 Low"}[severity]
    files_md = "\n".join(f"- `{f.strip()}`" for f in files.split(","))
    return f"""### GP-{n} — {title}
**Status:** {status}
**Description:** {desc}
**User Impact:** {impact}
**Root Cause:** {root_cause}
**Progress:** None yet.
**Related Files:**
{files_md}
**Fix:** {fix}
**Severity:** {sev_icon}
**Category:** {category}

"""


def main():
    out = [
        "\n\n## Session GP Findings — Full-Review, Group 7 (Platform & Ops)\n\n",
        "Appended 2026-08-05 from Phase 1 investigation (20 parallel sub-agents scoped to Group 7).\n\n",
    ]
    for f in FINDINGS:
        out.append(render_entry(*f))
    body = "".join(out)
    # Append to review.md
    with REVIEW.open("a", encoding="utf-8") as fp:
        fp.write(body)
    print(f"Appended {len(FINDINGS)} GP-N findings to {REVIEW}")
    # Count by severity
    sev_counts = {}
    for f in FINDINGS:
        sev_counts[f[2]] = sev_counts.get(f[2], 0) + 1
    print("Severity counts:", sev_counts)


if __name__ == "__main__":
    main()
